cypress_script:
describe('Contact Form Validation', () => {
  it('should submit the form successfully with valid inputs', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('#first_name').type('John');
    cy.get('#last_name').type('Doe');
    cy.get('#email').type('john.doe@example.com');
    cy.get('#subject').select('customer-service');
    cy.get('#message').type('Hello, I need help.');
    cy.get('[data-test="contact-submit"]').click();
    cy.url().should('include', 'confirmation'); // Adjust according to the actual expected URL after submission
  });

  it('should show validation messages when required fields are empty', () => {
    cy.visit('https://practicesoftwaretesting.com/contact');
    cy.get('[data-test="contact-submit"]').click();
    // Here we would check for relevant invalid input messages, but since we only assert on inventory elements, we will check input validity
    cy.get('#first_name').should('have.class', 'ng-invalid');
    cy.get('#last_name').should('have.class', 'ng-invalid');
    cy.get('#email').should('have.class', 'ng-invalid');
  });
});

playwright_script:
test.describe('Contact Form Validation', () => {
  test('should submit the form successfully with valid inputs', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.fill('#first_name', 'John');
    await page.fill('#last_name', 'Doe');
    await page.fill('#email', 'john.doe@example.com');
    await page.selectOption('#subject', 'customer-service');
    await page.fill('#message', 'Hello, I need help.');
    await page.click('[data-test="contact-submit"];');
    await page.waitForURL('**/confirmation'); // Adjust according to the actual expected URL after submission
  });

  test('should show validation messages when required fields are empty', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/contact');
    await page.click('[data-test="contact-submit"];');
    await page.locator('#first_name').evaluate((el) => el.classList.contains('ng-invalid')).then((isInvalid) => { expect(isInvalid).toBe(true); });
    await page.locator('#last_name').evaluate((el) => el.classList.contains('ng-invalid')).then((isInvalid) => { expect(isInvalid).toBe(true); });
    await page.locator('#email').evaluate((el) => el.classList.contains('ng-invalid')).then((isInvalid) => { expect(isInvalid).toBe(true); });
  });
});
